import React,{useEffect,useState}from'react';import{LayoutTemplate,Save,Plus,Trash2}from'lucide-react';import{notifyError,notifySuccess}from'../../lib/notify';import{fetchSupportCenterQuickActions,saveSupportCenterQuickAction,deleteSupportCenterQuickAction,fetchKnowledgeDocuments,saveSupportFaq,deleteSupportFaq}from'../../services/api';
const sections=[['overview','Overview'],['new-ticket','Open Ticket'],['my-tickets','My Tickets'],['live-support','Live Support'],['faq','FAQ'],['contact','Contact Support']];
export default function SupportCenterBuilder({settings={},onSaveSettings}){const base={support_center_title:'Support & Help Center',support_center_subtitle:'We are here to help you with your account, payments and investments.',support_center_badge:'24/7 Assistance',support_center_response_time:'Usually replies within 5 minutes',support_overview_enabled:true,support_ticket_form_enabled:true,support_my_tickets_enabled:true,support_live_chat_enabled:true,support_faq_enabled:true,support_contact_enabled:true,support_section_order:sections.map(([id])=>id)};const[form,setForm]=useState({...base,...settings}),[actions,setActions]=useState([]),[faqs,setFaqs]=useState([]),[saved,setSaved]=useState(false),[newAction,setNewAction]=useState({label:'',description:''}),[newFaq,setNewFaq]=useState({title:'',content:'',category:'General FAQ'});useEffect(()=>{setForm({...base,...settings});Promise.all([fetchSupportCenterQuickActions(),fetchKnowledgeDocuments()]).then(([a,d])=>{setActions(a);setFaqs(d)}).catch(()=>{})},[settings]);const update=(k,v)=>setForm(x=>({...x,[k]:v}));const save=async e=>{e.preventDefault();try{await onSaveSettings(form);setSaved(true);notifySuccess('Support Center Saved','Settings saved to database.');setTimeout(()=>setSaved(false),1800)}catch(e){notifyError('Save Failed',e.message)}};const add=async()=>{if(!newAction.label.trim())return;try{const item=await saveSupportCenterQuickAction({...newAction,target_tab:'new-ticket',sort_order:actions.length+1,enabled:true});setActions(x=>[...x,item]);setNewAction({label:'',description:''})}catch(e){notifyError('Action Failed',e.message)}};const remove=async id=>{try{await deleteSupportCenterQuickAction(id);setActions(x=>x.filter(a=>a.id!==id))}catch(e){notifyError('Delete Failed',e.message)}};const move=(i,d)=>{let x=[...form.support_section_order],t=i+d;if(t<0||t>=x.length)return;[x[i],x[t]]=[x[t],x[i]];update('support_section_order',x)};return <form onSubmit={save} className="builder"><header><div><LayoutTemplate/> <b>Support Center Builder</b></div>{saved&&<span>Saved to database</span>}</header><div className="grid2"><label>Page title<input value={(form.support_center_title ?? '')} onChange={e=>update('support_center_title',e.target.value)}/></label><label>Hero badge<input value={(form.support_center_badge ?? '')} onChange={e=>update('support_center_badge',e.target.value)}/></label></div><label>Subtitle<textarea rows={2} value={form.support_center_subtitle} onChange={e=>update('support_center_subtitle',e.target.value)}/></label><label>Response time<input value={(form.support_center_response_time ?? '')} onChange={e=>update('support_center_response_time',e.target.value)}/></label><div><strong>Visible sections</strong><div className="grid2">{[['support_overview_enabled','Overview'],['support_ticket_form_enabled','Open Ticket'],['support_my_tickets_enabled','My Tickets'],['support_live_chat_enabled','Live Support'],['support_faq_enabled','FAQ'],['support_contact_enabled','Contact Support']].map(([k,l])=><button type="button" key={k} onClick={()=>update(k,!form[k])}>{l}<b>{form[k]?'ON':'OFF'}</b></button>)}</div></div><div><strong>Section order</strong>{form.support_section_order.map((id,i)=><div className="row" key={id}>{i+1}. {sections.find(x=>x[0]===id)?.[1]||id}<span><button type="button" onClick={()=>move(i,-1)}>↑</button><button type="button" onClick={()=>move(i,1)}>↓</button></span></div>)}</div><div><strong>Quick actions</strong>{actions.map(a=><div className="row" key={a.id}>{a.label}<button type="button" onClick={()=>remove(a.id)}><Trash2/></button></div>)}<div className="grid2"><input value={(newAction.label ?? '')} onChange={e=>setNewAction({...newAction,label:e.target.value})} placeholder="Action label"/><input value={(newAction.description ?? '')} onChange={e=>setNewAction({...newAction,description:e.target.value})} placeholder="Description"/></div><button type="button" onClick={add} className="save"><Plus/>Add Action</button></div><button className="save"><Save/>Save Support Center</button><style>{`.builder{background:#071738;border:1px solid #173b7d;border-radius:1rem;padding:1.25rem;color:#cbd5e1;display:flex;flex-direction:column;gap:.8rem}.builder header,.builder .row{display:flex;justify-content:space-between;align-items:center}.builder header div{display:flex;gap:.5rem;align-items:center;color:#fbbf24}.builder header span{color:#6ee7b7}.builder label,.builder strong{color:#fbbf24;font-weight:900}.builder input,.builder textarea{display:block;width:100%;margin-top:.3rem;padding:.65rem;border-radius:.6rem;background:#030c1f;border:1px solid #173a78;color:white}.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}.builder button{padding:.55rem .7rem;border-radius:.55rem;background:#030c1f;border:1px solid #173b7d;color:#cbd5e1;font-size:.72rem}.builder button b{float:right;color:#6ee7b7}.builder .row{padding:.5rem;background:#030c1f;border:1px solid #173b7d;border-radius:.5rem;margin-top:.3rem}.builder .row button{padding:.2rem .4rem;margin-left:.25rem}.builder .row svg{width:14px}.builder .save{background:#fbbf24;color:#020617;font-weight:900;display:inline-flex;align-items:center;gap:.4rem;width:max-content}.builder .save svg{width:15px}`}</style></form>}