import React, { useEffect, useState } from 'react';
import { Ticket, RefreshCw, Send, CheckCircle2 } from 'lucide-react';
import { notifyError, notifyConfirm } from '../../lib/notify';
import { fetchSupportTickets, fetchSupportTicketMessages, markTicketSeen, sendSupportTicketReply, updateSupportTicket } from '../../services/api';

export default function SupportTickets() {
  const [tickets, setTickets] = useState([]); const [active, setActive] = useState(null); const [messages, setMessages] = useState([]); const [reply, setReply] = useState(''); const [status, setStatus] = useState(''); const [filter, setFilter] = useState('ALL');
  const load = async () => { try { setTickets(await fetchSupportTickets()); } catch (e) { notifyError('Tickets Load Failed', e.message); } };
  useEffect(() => { load(); }, []);
  const open = async (ticket) => { setActive({ ...ticket, unread_for_admin: 0 }); setTickets((rows) => rows.map((row) => row.id === ticket.id ? { ...row, unread_for_admin: 0 } : row)); setStatus(''); markTicketSeen(ticket.id, 'ADMIN').catch(() => {}); try { setMessages(await fetchSupportTicketMessages(ticket.id)); } catch (e) { notifyError('Ticket Messages Failed', e.message); } };
  const send = async (e) => { e.preventDefault(); if (!reply.trim() || !active || active.status === 'CLOSED') return; try { await sendSupportTicketReply({ ticketId: active.id, content: reply.trim() }); setReply(''); setStatus('SENT'); setMessages(await fetchSupportTicketMessages(active.id)); await load(); } catch (e) { setStatus('FAILED'); notifyError('Ticket Reply Failed', e.message); } };
  const update = async (values) => {
    if (values.status === 'CLOSED' && active?.status !== 'CLOSED') {
      const confirmed = await notifyConfirm('Close ticket permanently?', 'After closing, this ticket cannot be reopened, edited, or replied to.', 'Close Permanently');
      if (!confirmed) return;
    }
    try { const saved = await updateSupportTicket(active.id, values); setActive(saved); await load(); } catch (e) { notifyError('Ticket Update Failed', e.message); }
  };

  return <div className="bg-[#071738] border border-[#173b7d] rounded-2xl p-5 shadow-xl space-y-4"><div className="flex items-center justify-between pb-3 border-b border-[#173b7d]"><div className="flex items-center gap-2"><Ticket className="w-5 h-5 text-amber-400"/><h3 className="font-black text-white text-sm">Support Tickets</h3><select value={filter} onChange={(e) => setFilter(e.target.value)} className="bg-[#030c1f] border border-[#173b7d] rounded px-2 py-1 text-[10px] text-white"><option>ALL</option><option>OPEN</option><option>IN_PROGRESS</option><option>WAITING_FOR_USER</option><option>RESOLVED</option><option>CLOSED</option></select><span className="text-[10px] text-slate-400">{tickets.length} tickets</span></div><button onClick={load} className="p-2 rounded-lg bg-[#030c1f] text-slate-300"><RefreshCw className="w-4 h-4"/></button></div><div className="grid lg:grid-cols-12 gap-4"><div className="lg:col-span-4 space-y-2 max-h-[560px] overflow-y-auto">{tickets.filter((ticket) => filter === 'ALL' || ticket.status === filter).map((ticket) => <button key={ticket.id} onClick={() => open(ticket)} className={`w-full text-left p-3 rounded-xl border ${active?.id === ticket.id ? 'border-amber-400 bg-[#0c265e]' : 'border-[#173b7d] bg-[#030c1f]'}`}><p className="text-xs font-bold text-white truncate">{ticket.subject}</p><p className="text-[10px] text-amber-300">{ticket.user_name || 'Guest User'} · ID: {ticket.user_id || 'Guest'}</p><p className="text-[10px] text-slate-400 truncate">{ticket.user_email || 'Email unavailable'} · {ticket.category} · {ticket.status}</p></button>)}{!tickets.length && <p className="text-xs text-slate-400 text-center py-8">No tickets yet.</p>}</div><div className="lg:col-span-8 bg-[#030c1f] rounded-xl border border-[#173b7d] min-h-[420px]">{!active ? <p className="text-xs text-slate-500 text-center py-20">Select a ticket.</p> : <><div className="p-3 border-b border-[#173b7d] flex justify-between gap-2"><div><p className="text-sm font-black text-white">{active.subject}</p><p className="text-[10px] text-amber-300">User ID: {active.user_id || 'Guest'} · {active.category}</p></div><div className="flex gap-2"><select disabled={active.status === 'CLOSED'} value={active.status} onChange={(e) => update({ status: e.target.value })} className="bg-[#071738] text-white text-[10px] rounded p-1"><option>OPEN</option><option>IN_PROGRESS</option><option>WAITING_FOR_USER</option><option>RESOLVED</option><option>CLOSED</option></select><select value={active.priority} onChange={(e) => update({ priority: e.target.value })} className="bg-[#071738] text-white text-[10px] rounded p-1"><option>LOW</option><option>NORMAL</option><option>HIGH</option><option>URGENT</option></select></div></div><div className="p-3 space-y-2 max-h-[360px] overflow-y-auto">{messages.map((item) => <div key={item.id} className={`flex ${item.sender_type === 'USER' ? 'justify-end' : 'justify-start'}`}><div className={`max-w-[80%] rounded-xl px-3 py-2 text-xs ${item.sender_type === 'USER' ? 'bg-amber-400 text-slate-950' : 'bg-[#0c265e] text-slate-200'}`}>{item.content}<p className="text-[9px] mt-1 opacity-60">{item.sender_type} · {item.message_status || 'SENT'}</p></div></div>)}</div>{active.status === 'CLOSED' && <div className="mx-3 mb-3 rounded-xl border border-slate-600 bg-slate-800/60 p-3 text-xs text-slate-300">🔒 This ticket is closed. Reopen it before replying.</div>}<form onSubmit={send} className="p-3 border-t border-[#173b7d] flex gap-2">{status && <span className={`text-[10px] self-center ${status === 'SENT' ? 'text-emerald-300' : 'text-rose-300'}`}>{status === 'SENT' ? '✓ Sent' : '✕ Failed'}</span>}<div className="flex-1 rounded-xl bg-[#071738] border border-[#173a78] focus-within:border-amber-400"><textarea disabled={active.status === 'CLOSED'} value={reply} onChange={(e) => setReply(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); e.currentTarget.form?.requestSubmit(); } }} rows={2} maxLength={2000} placeholder={active.status === 'CLOSED' ? 'Ticket closed' : 'Write your ticket reply...'} className="w-full resize-none bg-transparent px-3 py-2 text-white text-xs outline-none disabled:opacity-50"/><div className="px-3 pb-1 text-right text-[9px] text-slate-500">{reply.length}/2000</div></div><button disabled={active.status === 'CLOSED' || !reply.trim()} className="px-4 rounded-xl bg-amber-400 text-slate-950 font-black text-xs disabled:opacity-40"><Send className="w-3.5 h-3.5 inline"/> Send</button></form><div className="px-3 pb-3 flex justify-end">{active.status === 'CLOSED' && <span className="text-[10px] text-slate-500">Permanently closed {active.closed_at ? `· ${new Date(active.closed_at).toLocaleString()}` : ''}</span>}</div></>}</div></div></div>;
}