import React, { useEffect, useState } from 'react';
import { Inbox as InboxIcon, RefreshCw, Send, MailOpen } from 'lucide-react';
import { notifyError } from '../../lib/notify';
import { fetchContactInquiries, fetchContactReplies, sendContactReply, updateContactInquiry } from '../../services/api';

export default function Inbox() {
  const [items, setItems] = useState([]); const [active, setActive] = useState(null); const [replies, setReplies] = useState([]); const [reply, setReply] = useState(''); const [state, setState] = useState('');
  const load = async () => { try { setItems(await fetchContactInquiries()); } catch (e) { notifyError('Inbox Load Failed', e.message); } };
  useEffect(() => { load(); }, []);
  const open = async (item) => { setActive(item); setState(''); try { const [rows] = await Promise.all([fetchContactReplies(item.id), updateContactInquiry(item.id, { is_read: true })]); setReplies(rows); await load(); } catch (e) { notifyError('Message Load Failed', e.message); } };
  const send = async (e) => { e.preventDefault(); if (!reply.trim() || !active) return; try { await sendContactReply({ messageId: active.id, content: reply.trim() }); setReply(''); setState('SENT'); setReplies(await fetchContactReplies(active.id)); } catch (e) { setState('FAILED'); notifyError('Reply Failed', e.message); } };
  return <div className="bg-[#071738] border border-[#173b7d] rounded-2xl p-5 shadow-xl space-y-4"><div className="flex justify-between items-center border-b border-[#173b7d] pb-3"><div className="flex items-center gap-2"><InboxIcon className="w-5 h-5 text-amber-400"/><h3 className="text-sm font-black text-white">Inbox</h3><span className="text-[10px] text-slate-400">{items.filter((x) => !x.is_read).length} unread</span></div><button onClick={load} className="p-2 bg-[#030c1f] rounded-lg text-slate-300"><RefreshCw className="w-4 h-4"/></button></div><div className="grid lg:grid-cols-12 gap-4"><div className="lg:col-span-5 space-y-2 max-h-[560px] overflow-y-auto sr-scroll-x">{items.map((item) => <button key={item.id} onClick={() => open(item)} className={`w-full text-left p-3 rounded-xl border ${active?.id === item.id ? 'border-amber-400 bg-[#0c265e]' : 'border-[#173b7d] bg-[#030c1f]'}`}><div className="flex justify-between gap-2"><span className="text-xs font-bold text-white truncate">{item.name}</span>{!item.is_read && <span className="text-[9px] text-amber-300 font-black">NEW</span>}</div><p className="text-[10px] text-cyan-300 truncate">{item.email}</p><p className="text-[10px] text-slate-400 truncate">{item.message}</p><p className="text-[9px] text-slate-500">{item.created_at ? new Date(item.created_at).toLocaleString() : ''}</p></button>)}{!items.length && <p className="text-xs text-slate-400 text-center py-8">Inbox is empty.</p>}</div><div className="lg:col-span-7 bg-[#030c1f] border border-[#173b7d] rounded-xl min-h-[420px]">{!active ? <p className="text-xs text-slate-500 text-center py-20">Select a contact message.</p> : <><div className="p-4 border-b border-[#173b7d]"><p className="text-sm font-black text-white">{active.name}</p><p className="text-[10px] text-cyan-300">{active.email}</p><p className="text-xs text-slate-300 mt-3 whitespace-pre-wrap">{active.message}</p></div><div className="p-3 space-y-2 max-h-[280px] overflow-y-auto">{replies.map((item) => <div key={item.id} className="bg-[#0c265e] rounded-xl p-3 text-xs text-slate-200">{item.content}<p className="text-[9px] opacity-60 mt-1">{item.sender_type} · {item.message_status}</p></div>)}</div><form onSubmit={send} className="p-3 border-t border-[#173b7d] flex gap-2">{state && <span className={`self-center text-[10px] ${state === 'SENT' ? 'text-emerald-300' : 'text-rose-300'}`}>{state === 'SENT' ? '✓ Sent' : '✕ Failed'}</span>}<input value={(reply ?? '')} onChange={(e) => setReply(e.target.value)} placeholder="Reply to email inquiry..." className="flex-1 bg-[#071738] border border-[#173a78] rounded-xl px-3 text-white text-xs"/><button className="px-4 rounded-xl bg-amber-400 text-slate-950 font-black text-xs"><Send className="w-3.5 h-3.5 inline"/> Send</button></form></>}</div></div></div>;
}