import React, { useEffect, useState } from 'react';
import { SlidersHorizontal, Save, Eye } from 'lucide-react';
import { notifyError, notifySuccess } from '../../lib/notify';

export default function SupportCustomization({ settings = {}, onSaveSettings }) {
  const [form, setForm] = useState({
    live_support_label: (settings as any).live_support_label || 'Live Support',
    live_support_welcome_message: (settings as any).live_support_welcome_message || 'Welcome to SR Investment Live Support. How can we help you?',
    live_support_offline_message: (settings as any).live_support_offline_message || 'Our support team is currently offline. Please leave a message.',
    live_support_guest_enabled: (settings as any).live_support_guest_enabled ?? true,
    live_support_handoff_enabled: (settings as any).live_support_handoff_enabled ?? true,
    live_support_sound_enabled: (settings as any).live_support_sound_enabled ?? true,
    live_support_notifications_enabled: (settings as any).live_support_notifications_enabled ?? true,
    live_support_business_hours: (settings as any).live_support_business_hours || { start: '09:00', end: '21:00', timezone: 'Asia/Dhaka' },
    support_logo_url: (settings as any).support_logo_url || '',
    support_ai_avatar_url: (settings as any).support_ai_avatar_url || '',
    support_agent_avatar_url: (settings as any).support_agent_avatar_url || '',
    support_widget_avatar_url: (settings as any).support_widget_avatar_url || '',
    support_theme: (settings as any).support_theme || 'navy-gold',
    support_primary_color: (settings as any).support_primary_color || '#071738',
    support_accent_color: (settings as any).support_accent_color || '#fbbf24',
    support_header_color: (settings as any).support_header_color || '#0e3b91',
    support_user_bubble_color: (settings as any).support_user_bubble_color || '#fbbf24',
    support_agent_bubble_color: (settings as any).support_agent_bubble_color || '#0c265e',
    support_widget_position: (settings as any).support_widget_position || 'bottom-right',
    support_widget_size: (settings as any).support_widget_size || 'standard',
    support_border_radius: (settings as any).support_border_radius || 'large',
    support_open_animation: (settings as any).support_open_animation || 'slide-up',
    support_message_animation: (settings as any).support_message_animation || 'fade',
    support_button_animation: (settings as any).support_button_animation || 'pulse',
    support_animation_speed: (settings as any).support_animation_speed || 'normal',
    support_time_format: (settings as any).support_time_format || '24-hour',
    support_date_format: (settings as any).support_date_format || 'DD/MM/YYYY',
    support_language: (settings as any).support_language || 'en',
    support_quick_replies_enabled: (settings as any).support_quick_replies_enabled ?? true,
    support_typing_indicator_enabled: (settings as any).support_typing_indicator_enabled ?? true,
    support_auto_scroll_enabled: (settings as any).support_auto_scroll_enabled ?? true,
    support_realtime_enabled: (settings as any).support_realtime_enabled ?? true
  });
  const [saved, setSaved] = useState(false);
  useEffect(() => setForm((current) => ({ ...current, ...settings, live_support_business_hours: (settings as any).live_support_business_hours || current.live_support_business_hours })), [settings]);
  const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const uploadAsset = (key, event) => { const file = event.target.files?.[0]; if (!file || !file.type.startsWith('image/')) return; if (file.size > 1024 * 1024) return; const reader = new FileReader(); reader.onload = () => update(key, String(reader.result || '')); reader.readAsDataURL(file); };
  const themes = { 'navy-gold': ['#071738', '#fbbf24', '#0e3b91'], emerald: ['#062a25', '#34d399', '#047857'], royal: ['#0b1f4d', '#60a5fa', '#2563eb'], purple: ['#21133d', '#c084fc', '#9333ea'], light: ['#f8fafc', '#2563eb', '#dbeafe'] };
  const applyTheme = (theme) => { const [primary, accent, header] = themes[theme]; setForm((current) => ({ ...current, support_theme: theme, support_primary_color: primary, support_accent_color: accent, support_header_color: header, support_user_bubble_color: accent })); };
  const save = async (event) => { event.preventDefault(); try { await onSaveSettings(form); setSaved(true); notifySuccess('Support Settings Saved', 'Live support customization updated.'); setTimeout(() => setSaved(false), 2000); } catch (e) { notifyError('Save Failed', e.message); } };
  return <form onSubmit={save} className="bg-[#071738] border border-[#173b7d] rounded-2xl p-5 shadow-xl space-y-5 text-xs"><div className="flex items-center justify-between border-b border-[#173b7d] pb-3"><div className="flex items-center gap-2 text-amber-400"><SlidersHorizontal className="w-5 h-5"/><h3 className="font-black text-white text-sm">Support Customization</h3></div>{saved && <span className="text-emerald-300 font-bold">Saved</span>}</div><div className="grid md:grid-cols-2 gap-3"><label className="text-slate-300">Widget label<input value={(form.live_support_label ?? '')} onChange={(e) => update('live_support_label', e.target.value)} className="field w-full"/></label><label className="text-slate-300">Timezone<select value={form.live_support_business_hours.timezone} onChange={(e) => update('live_support_business_hours', { ...form.live_support_business_hours, timezone: e.target.value })} className="field w-full"><option value="Asia/Dhaka">Bangladesh Standard Time (UTC+06:00)</option><option value="Asia/Kolkata">India Standard Time (UTC+05:30)</option><option value="Asia/Karachi">Pakistan Standard Time (UTC+05:00)</option><option value="Asia/Dubai">Gulf Standard Time (UTC+04:00)</option><option value="Asia/Riyadh">Arabia Standard Time (UTC+03:00)</option><option value="Asia/Singapore">Singapore Time (UTC+08:00)</option><option value="Asia/Kuala_Lumpur">Malaysia Time (UTC+08:00)</option><option value="Asia/Tokyo">Japan Standard Time (UTC+09:00)</option><option value="Europe/London">United Kingdom Time</option><option value="Europe/Paris">Central European Time</option><option value="America/New_York">Eastern US Time</option><option value="America/Chicago">Central US Time</option><option value="America/Los_Angeles">Pacific US Time</option><option value="Australia/Sydney">Australian Eastern Time</option><option value="UTC">UTC</option></select></label></div><div className="grid md:grid-cols-2 gap-3">{[['support_logo_url','Support logo'],['support_ai_avatar_url','AI avatar'],['support_agent_avatar_url','Agent avatar'],['support_widget_avatar_url','Widget avatar']].map(([key,label]) => <label key={key} className="text-slate-300">{label}<div className="flex gap-2 mt-1"><input value={(form[key] ?? '')} onChange={(e) => update(key, e.target.value)} placeholder="Image URL" className="field w-full"/><label className="px-2 py-2 rounded bg-[#0c265e] border border-[#1d4ed8] text-[10px] cursor-pointer">Upload<input type="file" accept="image/*" onChange={(e) => uploadAsset(key,e)} className="hidden"/></label></div>{form[key] && <img src={form[key]} alt={label} className="mt-2 w-10 h-10 rounded-full object-cover border border-amber-400/40"/>}</label>)}</div><div className="grid md:grid-cols-2 gap-3"><label className="text-slate-300">Theme<select value={form.support_theme} onChange={(e) => applyTheme(e.target.value)} className="field w-full"><option value="navy-gold">Navy Gold</option><option value="emerald">Emerald</option><option value="royal">Royal Blue</option><option value="purple">Purple</option><option value="light">Light Clean</option></select></label><label className="text-slate-300">Position<select value={form.support_widget_position} onChange={(e) => update('support_widget_position', e.target.value)} className="field w-full"><option value="bottom-right">Bottom Right</option><option value="bottom-left">Bottom Left</option><option value="top-right">Top Right</option><option value="top-left">Top Left</option></select></label><label className="text-slate-300">Size<select value={form.support_widget_size} onChange={(e) => update('support_widget_size', e.target.value)} className="field w-full"><option value="compact">Compact</option><option value="standard">Standard</option><option value="large">Large</option></select></label><label className="text-slate-300">Open animation<select value={form.support_open_animation} onChange={(e) => update('support_open_animation', e.target.value)} className="field w-full"><option value="slide-up">Slide Up</option><option value="fade">Fade</option><option value="scale">Scale</option><option value="none">None</option></select></label><label className="text-slate-300">Language<select value={form.support_language} onChange={(e) => update('support_language', e.target.value)} className="field w-full"><option value="en">English</option><option value="bn">বাংলা</option><option value="hi">हिन्दी</option><option value="ar">العربية</option><option value="ms">Malay</option></select></label><label className="text-slate-300">Accent<input type="color" value={(form.support_accent_color ?? '')} onChange={(e) => update('support_accent_color', e.target.value)} className="field w-full h-9"/></label></div><div className="rounded-xl border border-amber-400/30 p-3" style={{ background: form.support_primary_color }}><div className="flex items-center gap-2 text-white font-black"><Eye className="w-4 h-4"/> Live preview</div><div className="mt-2 p-2 rounded-xl text-xs" style={{ background: form.support_agent_bubble_color, color: '#fff' }}>Support widget preview message</div></div><label className="text-slate-300 block">Welcome message<textarea value={form.live_support_welcome_message} onChange={(e) => update('live_support_welcome_message', e.target.value)} rows={3} className="field w-full"/></label><label className="text-slate-300 block">Offline message<textarea value={form.live_support_offline_message} onChange={(e) => update('live_support_offline_message', e.target.value)} rows={3} className="field w-full"/></label><div className="grid md:grid-cols-2 gap-3"><label className="text-slate-300">Business start<input type="time" value={(form.live_support_business_hours.start ?? '')} onChange={(e) => update('live_support_business_hours', { ...form.live_support_business_hours, start: e.target.value })} className="field w-full"/></label><label className="text-slate-300">Business end<input type="time" value={(form.live_support_business_hours.end ?? '')} onChange={(e) => update('live_support_business_hours', { ...form.live_support_business_hours, end: e.target.value })} className="field w-full"/></label></div><div className="grid sm:grid-cols-2 gap-2">{[['live_support_guest_enabled','Allow guest support'],['live_support_handoff_enabled','Allow human handoff'],['live_support_sound_enabled','Notification sound'],['live_support_notifications_enabled','Browser notifications']].map(([key,label]) => <button type="button" key={key} onClick={() => update(key, !form[key])} className="flex justify-between p-3 rounded-xl bg-[#030c1f] border border-[#173b7d] text-slate-300"><span>{label}</span><strong className={form[key] ? 'text-emerald-300' : 'text-rose-300'}>{form[key] ? 'ON' : 'OFF'}</strong></button>)}</div><button className="flex items-center gap-2 px-4 py-2 rounded-xl bg-amber-400 text-slate-950 font-black"><Save className="w-4 h-4"/> Save Customization</button><style>{`.field{margin-top:.35rem;padding:.65rem;border-radius:.65rem;background:#030c1f;border:1px solid #173a78;color:white;outline:none;font-size:.75rem}`}</style></form>;
}